"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4186],{7364:e=>{e.exports=JSON.parse('{"functions":[{"name":"sortByDistance","desc":"Orders targets nearest-observer-first.","params":[{"name":"a","desc":"","lua_type":"Target"},{"name":"b","desc":"","lua_type":"Target"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","private":true,"source":{"line":39,"path":"src/main/server/systems/maze/load.luau"}},{"name":"mark","desc":"Records a chunk as wanting generation, keeping the shortest distance if two\\nobservers both want it.","params":[{"name":"world","desc":"","lua_type":"jecs.World"},{"name":"pending","desc":"Accumulator, keyed by chunk key.","lua_type":"{ [string]: Target }"},{"name":"chunkX","desc":"Chunk column.","lua_type":"number"},{"name":"chunkY","desc":"Chunk row.","lua_type":"number"},{"name":"distance","desc":"Chebyshev distance to the observer that asked.","lua_type":"number"}],"returns":[],"function_type":"static","private":true,"source":{"line":55,"path":"src/main/server/systems/maze/load.luau"}},{"name":"collect","desc":"Collects every ungenerated chunk within the load radius of any observer,\\nsorted nearest first.","params":[{"name":"world","desc":"","lua_type":"jecs.World"},{"name":"streaming","desc":"","lua_type":"MazeStreaming"},{"name":"radius","desc":"Load radius in chunks.","lua_type":"number"}],"returns":[{"desc":"Chunks wanting generation, nearest first.","lua_type":"{ Target }"}],"function_type":"static","private":true,"source":{"line":77,"path":"src/main/server/systems/maze/load.luau"}},{"name":"load","desc":"Generates as many nearby chunks as the frame has left. Runs in\\n`Phases.PostUpdate`, last of the stages that spend the budget.\\n\\nGenerating a chunk is a single indivisible ~5ms unit, larger than the whole\\nframe allowance, so this stage always overruns when it runs at all. That is\\ntolerable only because it runs **after** `build`: the deadline is re-stamped\\nevery frame, so an overrun here costs the tail of this frame rather than\\nstarving the incremental stages, which get a fresh allowance next tick.\\n\\nIt still forces one chunk through per pass. Dropping that guarantee was tried\\nand is much worse \u2014 under sustained traversal `load` never won a frame at all\\nand the world failed to rebuild, ending a 12-hop run with an empty maze and\\n72.8% stalls.\\n\\nWrites `MazeStreaming.loadsOutstanding` \u2014 the only field this system owns \u2014\\nso `observers` keeps requesting resyncs until the backlog clears.\\n\\n**Deliberately not gated on `resyncNeeded`.** That flag is edge-triggered on\\nthe observers\' detail-block signature changing, but chunks can go missing for\\nreasons that have nothing to do with anyone moving \u2014 an unload, a teardown, a\\nmomentary gap in observer tracking. Gating on it stalled the pipeline for\\ngood: destroy a chunk inside the load radius while the player stands still and\\nnothing ever regenerated it, because a stationary player\'s signature never\\nchanges again. Since the world then stops growing, and streaming leaves the\\nclient with no ground, that also read as the character being unable to move.\\n\\nDetecting the gap is cheap enough to do unconditionally \u2014 a handful of table\\nlookups over the chunks in radius. Only `registry.ensure` is expensive, and\\nthat only runs when something is genuinely missing.","params":[{"name":"world","desc":"","lua_type":"jecs.World"}],"returns":[{"desc":"Update function.","lua_type":"() -> ()"},{"desc":"Cleanup function.","lua_type":"() -> ()"}],"function_type":"static","source":{"line":132,"path":"src/main/server/systems/maze/load.luau"}}],"properties":[],"types":[{"name":"Target","desc":"A chunk that wants generating.","fields":[{"name":"x","lua_type":"number","desc":"Chunk column."},{"name":"y","lua_type":"number","desc":"Chunk row."},{"name":"distance","lua_type":"number","desc":"Chebyshev distance to the nearest observer, in chunks."}],"source":{"line":28,"path":"src/main/server/systems/maze/load.luau"}}],"name":"load","desc":"Generates the chunks around every observer, nearest first, under a frame\\nbudget.","tags":["server-system"],"realm":["Server"],"source":{"line":9,"path":"src/main/server/systems/maze/load.luau"}}')}}]);